class Random {
  constructor() {
    this.useA = false;
    let sfc32 = function (uint128Hex) {
      let a = parseInt(uint128Hex.substr(0, 8), 16);
      let b = parseInt(uint128Hex.substr(8, 8), 16);
      let c = parseInt(uint128Hex.substr(16, 8), 16);
      let d = parseInt(uint128Hex.substr(24, 8), 16);
      return function () {
        a |= 0;
        b |= 0;
        c |= 0;
        d |= 0;
        let t = (((a + b) | 0) + d) | 0;
        d = (d + 1) | 0;
        a = b ^ (b >>> 9);
        b = (c + (c << 3)) | 0;
        c = (c << 21) | (c >>> 11);
        c = (c + t) | 0;
        return (t >>> 0) / 4294967296;
      };
    };
    // seed prngA with first half of tokenData.hash
    this.prngA = new sfc32(tokenData.hash.substr(2, 32));
    // seed prngB with second half of tokenData.hash
    this.prngB = new sfc32(tokenData.hash.substr(34, 32));
    for (let i = 0; i < 1e6; i += 2) {
      this.prngA();
      this.prngB();
    }
  }
  // random number between 0 (inclusive) and 1 (exclusive)
  random_dec() {
    this.useA = !this.useA;
    return this.useA ? this.prngA() : this.prngB();
  }
  // random number between a (inclusive) and b (exclusive)
  random_num(a, b) {
    return a + (b - a) * this.random_dec();
  }
  // random integer between a (inclusive) and b (inclusive)
  // requires a < b for proper probability distribution
  random_int(a, b) {
    return Math.floor(this.random_num(a, b + 1));
  }
  // random boolean with p as percent liklihood of true
  random_bool(p) {
    return this.random_dec() < p;
  }
  // random value in an array of items
  random_choice(list) {
    return list[this.random_int(0, list.length - 1)];
  }
}

const R = new Random();

function fetchData(_ix) {
  const data = sdata2[_ix];
  render(svg, data, GEOMETRIES, PALETTES);
}

function drawText(target, data, geometries, palettes, BGCol) {
  const d = data;

  const charSet = Object.keys(geometries);
  let color = "";
  if (BGCol === "GhostWhite") {
    color = "black";
  } else {
    color = "white";
  }

  let keyWords = [];
  keyWords = getKeywordsArray(d);
  let keyWordIndex = 0;
  let p = "";
  p = getRandPhrase(keyWords);
  let y = 0;
  let cellSize = chooseRnd([20, 29, 29, 58, 10, 18]);

  const numX2 = Math.floor(width / cellSize);
  const numY2 = Math.floor(height / cellSize);
  for (let j = 0; j < numY2; j++) {
    y = 15 + j * cellSize;
    for (let i = 0; i < numX2; i++) {
      const x = 10 + i * cellSize;

      char = p.charAt(keyWordIndex);
      if (keyWordIndex < p.length) {
        keyWordIndex++;
      } else {
        keyWordIndex = 0;
      }
      setChar(target, geometries, char, x, y, cellSize, color);
    }
    if (y < height) {
      p = getRandPhrase(keyWords);
    }
  }
}

function drawEmotionGrid(target, data, geometries, palettes, BGCol) {
  const width2 = svg.viewBox.baseVal.width - 20;
  const height2 = svg.viewBox.baseVal.height - 30;

  const cellSize = chooseRnd([5, 10, 20, 29, 58, 116]);
  const numX = Math.floor(width2 / cellSize);
  const numY = Math.floor(height2 / cellSize);
  const charSet = Object.keys(geometries);
  const charSet1 = charSet.slice(66, 72);
  const charSet2 = charSet.slice(87, 90);
  const charSet3 = charSet.slice(97, 103);
  const charSet4 = charSet.slice(83, 87);
  const charSet5 = charSet.slice(79, 86);
  const charSet6 = charSet.slice(94, 98);
  const charSet7 = charSet.slice(98, 104);
  const charSet8 = charSet.slice(61, 87);
  const charSet9 = charSet.slice(88, 94);

  let options = [
    [charSet, 3],
    [charSet1, 7],
    [charSet2, 10],
    [charSet3, 25],
    [charSet4, 10],
    [charSet5, 5],
    [charSet6, 10],
    [charSet7, 10],
    [charSet8, 5],
    [charSet9, 15],
  ];
  const currentCharSet = wchoice(options);
  let numIdx = 0;
  let joyScores = getEmotionScoreArray(data, "joy");
  let sadScores = getEmotionScoreArray(data, "sadness");
  knuthShuffle(currentCharSet);
  const randPalette = randomObjectProperty(PALETTES);
  for (let j = 0; j < numY; j++) {
    for (let i = 0; i < numX; i++) {
      const x = 10 + i * cellSize;
      const y = 15 + j * cellSize;

      if (numIdx < joyScores.length) {
        numIdx++;
      } else {
        numIdx = 0;
      }
      let idx2 = Math.floor(
        map_range(joyScores[numIdx], 0.0, 1.0, 0, randPalette.value.length)
      );
      color = choose(randPalette.value, idx2);
      let idxSad = Math.floor(
        map_range(sadScores[numIdx], 0.0, 1.0, 0, currentCharSet.length)
      );
      char = choose(currentCharSet, idxSad);
      setChar(target, geometries, char, x, y, cellSize, color);
    }
  }
}

function drawRandomText(target, data, geometries, palettes, BGCol) {
  const width2 = svg.viewBox.baseVal.width - 20; // 580
  const height2 = svg.viewBox.baseVal.height - 30; // 770
  const cellSize = chooseRnd([6, 8, 12, 14, 20]);
  const numX = Math.floor(width2 / cellSize);
  const numY = Math.floor(height2 / cellSize);
  const pal = chooseRnd(palettes);

  const charSet = Object.keys(geometries);
  let numIdx = 0;
  let joyScores = getEmotionScoreArray(data, "joy");
  let char = chooseRnd(charSet);
  let keyWords = [];
  keyWords = getKeywordsArray(data);
  let keyWordIndex = 0;
  let color = chooseRnd(PALETTES);
  if (BGCol === "GhostWhite") {
    color = "black";
  } else {
    color = "white";
  }
  const randPalette = randomObjectProperty(PALETTES);
  let y = 0;
  p = getRandPhrase(keyWords);
  for (let j = 0; j < numY; j++) {
    y = 15 + j * cellSize;
    for (let i = 0; i < numX; i++) {
      const x = 10 + i * cellSize;
      if (numIdx < joyScores.length) {
        numIdx++;
      } else {
        numIdx = 0;
      }
      char = p.charAt(keyWordIndex);
      if (keyWordIndex < p.length) {
        keyWordIndex++;
      } else {
        keyWordIndex = 0;
      }
      setChar(target, geometries, char, x, y, cellSize, color);
    }
  }
}

function drawGlyph(target, data, geometries, palettes, BGCol) {
  const cellSize = 116;
  const charSet = Object.keys(geometries);

  const charSetHeart = charSet.slice(87, 88);
  const arrows = charSet.slice(66, 68);
  charSetHeart.push.apply(charSetHeart, arrows);
  const currentCharSet = charSetHeart;

  let color = "white";
  const numX2 = Math.floor(width / cellSize);
  const numY2 = Math.floor(height / cellSize);

  for (let j = 0; j < numY2; j++) {
    for (let i = 0; i < numX2; i++) {
      const x = 10 + i * cellSize;
      const y = 15 + j * cellSize;

      if (R.random_dec() < 0.13) {
        let char = chooseRnd(currentCharSet);
        setChar(target, geometries, char, x, y, cellSize, color);
      }
    }
  }
}

function getRandPhrase(d) {
  return d[Math.floor(R.random_dec() * d.length)];
}
function chooseRnd(array) {
  return array[Math.floor(R.random_dec() * array.length)];
}
function choose(_array, _ix) {
  return _array[_ix];
}
const randomObjectProperty = (object) => {
  const keys = Object.keys(object);
  if (keys.length > 0) {
    const index = Math.floor(R.random_dec() * keys.length);
    const key = keys[index];
    const value = object[key];
    return {
      index,
      key,
      value,
    };
  }
  return null;
};
function getRandObject(obj) {
  return obj.value[Math.floor(R.random_dec() * obj.value.length)];
}
const knuthShuffle = (arr) => {
  let rand, temp, i;
  for (i = arr.length - 1; i > 0; i--) {
    rand = Math.floor((i + 1) * R.random_dec());
    let temp = [arr[i], arr[rand]];
    arr[rand] = temp[0];
    arr[i] = temp[1];
  }
  return arr;
};
function wchoice(options) {
  let opt = [];
  for (let o of options) {
    for (let i = 0; i < o[1]; i++) {
      opt.push(o[0]);
    }
  }
  let choice = Math.floor(R.random_dec() * opt.length);
  return opt[choice];
}

/*
function randomBias(min, max, bias, influence = 0.5) {
    const base = Math.abs(R.random_dec() * (min - max + 1) + max)
    const mix = R.random_dec() * influence
    return base * (1 - mix) + bias * mix
} 
*/
function map_range(value, low1, high1, low2, high2) {
  return low2 + ((high2 - low2) * (value - low1)) / (high1 - low1);
}

function getKeywordsArray(d) {
  let k = [];
  for (let i = 0; i < d.result.keywords.length; i++) {
    k[i] = d.result.keywords[i].text;
  }
  return k;
}
function getKeywords(d) {
  return d.result.keywords;
}
function countPositiveSentiment(d) {
  let count = 0;
  const kw = d.result.keywords;
  for (let i = 0; i < kw.length; i++) {
    if (kw[i].sentiment.label === "positive") count++;
  }
  return count;
}
function countNegativeSentiment(d) {
  let count = 0;
  const kw = d.result.keywords;
  for (let i = 0; i < kw.length; i++) {
    if (kw[i].sentiment.label === "negative") count++;
  }
  return count;
}
function countEmotionScore(d, em) {
  let count = 0;
  for (let i = 0; i < d.result.keywords.length; i++) {
    if (d.result.keywords[i].emotion != null)
      count += d.result.keywords[i].emotion[em];
  }
  return count;
}
function getEmotionScoreArray(d, em) {
  let k = [];
  for (let i = 0; i < d.result.keywords.length; i++) {
    if (d.result.keywords[i].emotion != null)
      k[i] = d.result.keywords[i].emotion[em];
  }
  return k;
}
function saveSVG(target, fileName) {
  const serializer = new XMLSerializer();
  const svg_blob = new Blob([serializer.serializeToString(target)], {
    type: "image/svg+xml",
  });
  const url = window.URL.createObjectURL(svg_blob);
  const a = document.createElement("a");
  document.body.appendChild(a);
  a.href = url;
  a.download = fileName;
  a.click();
  document.body.removeChild(a);
}
function setChar(target, geometries, glyph, x, y, size, color) {
  const scale = (1 / 700) * size;
  const p = document.createElementNS(target.namespaceURI, "path");
  p.setAttribute(
    "transform",
    `translate(${x} ${y + size}) scale(${scale} -${scale})`
  );
  p.setAttribute("fill", color);
  if (geometries[glyph] != undefined) {
    p.setAttribute("d", geometries[glyph]);
  }
  target.appendChild(p);
}

